46	// Serial FMA chain length per iteration.
47	static constexpr size_t CHAIN_STEPS = 512;
48	
49	// Finite high-Hamming f64 patterns: |x| <= 2, so products stay <= 4 and
50	// 512-step sums stay < 2048 — the chain can never overflow or NaN, so
51	// every lane of every step is byte-exact comparable. Successive entries
52	// toggle many mantissa/sign bits (high gate-toggle activity).
53	static const uint64_t F64_FINITE[] = {
54	    0x3FF5555555555555ULL,   //  1.3333...
55	    0xBFFAAAAAAAAAAAAAULL,   // -1.6667...
56	    0x3FD5555555555555ULL,   //  0.3333...
57	    0xBFEAAAAAAAAAAAAAULL,   // -0.8333...
58	    0x0015555555555555ULL,   //  denormal +
59	    0x801AAAAAAAAAAAAAULL,   //  denormal -
60	    0x3FF0000000000000ULL,   //  1.0
61	    0xBFF0000000000000ULL,   // -1.0
62	    0x0005555555555555ULL,   //  denormal +
63	    0x800AAAAAAAAAAAAAULL,   //  denormal -
64	    0x3FF999999999999AULL,   //  1.6
65	    0xBFF6666666666667ULL,   // -1.4
66	    0x3FE5555555555555ULL,   //  0.6667...
67	    0xBFE6666666666667ULL,   // -0.7
68	    0x3FF3333333333333ULL,   //  1.2
69	    0xBFFCCCCCCCCCCCCDULL,   // -1.8
70	};
71	static constexpr size_t F64_FINITE_SIZE =
72	    sizeof(F64_FINITE) / sizeof(F64_FINITE[0]);
73	
74	// Deterministic seed generator (same family as other tests).
75	static inline uint64_t splitmix64(uint64_t x)
76	{
77	    uint64_t z = (x + 0x9E3779B97F4A7C15ULL);
78	    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
79	    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
80	    return z ^ (z >> 31);
81	}
