83	struct SveF64ChainData {
84	    size_t vl_d;   // svcntd() — f64 lanes per full vector
85	
86	    // Per-lane seed accumulators (finite, [1.0, 2.0)).
87	    std::vector<uint64_t> seeds_f64;
88	
89	    // f64 finite-chain operand streams, layout [step * vl_d + lane].
90	    std::vector<uint64_t> m_f64;
91	    std::vector<uint64_t> a_f64;
92	};
