96	// ---------------------------------------------------------------------------
97	// Scalar golden: identical operation order and indexing to the SVE chain
98	// (stream layout is [step * lanes + lane]).
99	// ---------------------------------------------------------------------------
100	static void f64_chain_golden(const SveF64ChainData *d, uint64_t *out)
101	{
102	    const size_t lanes = d->vl_d;
103	    for (size_t lane = 0; lane < lanes; ++lane) {
104	        uint64_t accw = d->seeds_f64[lane];
105	        double acc;
106	        memcpy(&acc, &accw, 8);
107	        for (size_t i = 0; i < CHAIN_STEPS; ++i) {
108	            double m, a;
109	            memcpy(&m, &d->m_f64[i * lanes + lane], 8);
110	            memcpy(&a, &d->a_f64[i * lanes + lane], 8);
111	            acc = std::fma(m, a, acc);
112	        }
113	        memcpy(&accw, &acc, 8);
114	        out[lane] = accw;
115	    }
116	}
117	
118	// ---------------------------------------------------------------------------
119	// Hardware chain (SVE, full runtime VL).
120	// ---------------------------------------------------------------------------
121	static void f64_chain_hw(const SveF64ChainData *d, uint64_t *out)
122	{
123	    const size_t lanes = d->vl_d;
124	    const svbool_t pg = svptrue_b64();
125	    svfloat64_t acc = svld1_f64(pg, reinterpret_cast<const double *>(d->seeds_f64.data()));
126	    for (size_t i = 0; i < CHAIN_STEPS; ++i) {
127	        svfloat64_t m = svld1_f64(pg, reinterpret_cast<const double *>(&d->m_f64[i * lanes]));
128	        svfloat64_t a = svld1_f64(pg, reinterpret_cast<const double *>(&d->a_f64[i * lanes]));
129	        acc = svmla_f64_x(pg, acc, m, a);
130	    }
131	    svst1_f64(pg, reinterpret_cast<double *>(out), acc);
132	}
