13	#define NEON_VECTOR_SIZE 4                // NEON 一次处理 4 个 int32
14	#define BLOCK_SIZE 16                     // 逻辑块大小（由 4 个 NEON 向量组成）
15	#define VECTORS_PER_BLOCK (BLOCK_SIZE / NEON_VECTOR_SIZE)  // = 4
16	#define NUM_BLOCKS 64                     // 块数量
17	#define TOTAL_ELEMENTS (BLOCK_SIZE * NUM_BLOCKS)  // = 1024
18	#define TOTAL_BYTES (TOTAL_ELEMENTS * sizeof(int32_t))
19	
20	struct TestData {
21	    alignas(16) int32_t *data;          // 16 字节对齐即可
22	    std::atomic<uint32_t> next_block;
23	    std::atomic<uint64_t> global_sum;
24	    std::atomic<uint32_t> write_done;
25	    std::atomic<uint32_t> read_done;
26	    std::atomic<uint32_t> reset_lock;
27	    std::atomic<uint32_t> thread_idx;
28	    uint32_t total_threads;
29	};
