43	{
44	    uint64_t z = (x + 0x9E3779B97F4A7C15ULL);
45	    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
46	    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
47	    return z ^ (z >> 31);
